CREATE TABLE IF NOT EXISTS install_request_previous_resolution (request_id VARCHAR(20) PRIMARY KEY, status VARCHAR(30) NOT NULL, resolved_by_type VARCHAR(30) NULL, resolved_by_id VARCHAR(20) NULL, resolved_at TIMESTAMP NULL, raw_scopes TEXT NULL, CONSTRAINT fk_install_request_previous_resolution_request_id__request_id FOREIGN KEY (request_id) REFERENCES install_request(request_id) ON DELETE RESTRICT ON UPDATE RESTRICT);